// Valida payload UAZAPI e extrai dados (texto ou audio).
const THIAGO_NUMEROS = ['5511964486564', '5511910441709'];

const body = items[0].json.body || items[0].json;
const msg = body.message || body.data || body;

// Ignorar fromMe
const fromMe = msg.fromMe === true || msg.key?.fromMe === true;
if (fromMe) return [];

// Ignorar grupos
const chatId = String(msg.chatid || msg.chatId || msg.key?.remoteJid || '');
if (chatId.includes('@g.us') || chatId.includes('-')) return [];

const senderNumero = chatId.replace(/@.*$/, '').replace(/[^0-9]/g, '');
if (!senderNumero || senderNumero.length < 10) return [];

// Timestamp Brasilia (UTC-3)
const agora = new Date(Date.now() - (3 * 60 * 60 * 1000));
const agoraISO = agora.toISOString().replace('T', ' ').substring(0, 19);
const ehThiago = THIAGO_NUMEROS.includes(senderNumero);
const messageId = msg.id || msg.messageid || msg.key?.id || '';

// Detectar audio (varios formatos UAZAPI/WA possiveis)
const messageType = String(msg.messageType || msg.type || msg.mediaType || '').toLowerCase();
const audioPayload = msg.audioMessage || msg.audio || msg.message?.audioMessage || null;
const isAudio = ['audio','audiomessage','voice','voicemessage','ptt'].includes(messageType) || !!audioPayload;

const base = {
  valido: true,
  eh_thiago: ehThiago,
  sender_numero: senderNumero,
  sender_nome_push: msg.pushName || msg.notifyName || '',
  timestamp_agora_brasilia: agoraISO,
  message_id: messageId,
  tem_audio: isAudio,
  audio_id: isAudio ? messageId : '',
  audio_mime: isAudio ? (msg.mimetype || audioPayload?.mimetype || 'audio/ogg') : '',
  audio_base64: ''
};

if (isAudio) {
  return [{ json: { ...base, texto: '' } }];
}

// Texto normal
const texto = msg.text || msg.body || msg.message?.conversation || msg.message?.extendedTextMessage?.text || msg.content || '';
if (!texto || !String(texto).trim()) return [];
return [{ json: { ...base, texto: String(texto).trim() } }];

// Combina resposta do download com o estado anterior
const prev = $('Validar Mensagem').first().json;
const resp = items[0].json || {};

// Tenta varios campos comuns onde UAZAPI pode entregar base64
const base64 = resp.base64
  || resp.data
  || resp.fileBase64
  || resp.audio?.base64
  || resp.media?.base64
  || resp.body?.base64
  || '';

const mime = resp.mimetype || resp.mime || prev.audio_mime || 'audio/ogg';

return [{
  json: {
    ...prev,
    audio_base64: base64,
    audio_mime: mime,
    audio_download_falhou: !base64,
    audio_download_raw_keys: Object.keys(resp).slice(0, 10).join(',')
  }
}];

// Pega o estado da msg do node mais proximo (Combinar Audio se passou por audio, ou Validar Mensagem direto)
function tryGet(name){
  try { return $(name).all().map(i => i.json).filter(x => x && x.sender_numero); } catch(e) { return []; }
}
const comb = tryGet('Combinar Audio');
const val = $('Validar Mensagem').all().map(i => i.json).filter(x => x && x.sender_numero);
const msgAtual = (comb[0]) || val[0] || {};

const memoria = $('Carregar Memoria').all().map(i => i.json);
const contatos = $('Carregar Contatos').all().map(i => i.json);
const leadArr = $('Carregar Lead').all().map(i => i.json).filter(x => x && x.numero);
const lead = leadArr[0] || null;

const contatosTxt = contatos.map(c => {
  const apelidos = Array.isArray(c.apelidos) ? c.apelidos.join(', ') : (c.apelidos || '');
  return `- ${c.nome} (apelidos: ${apelidos}) numero=${c.numero}${c.observacoes ? ' obs: '+c.observacoes : ''}`;
}).join('\n');

const memOrdenada = memoria.slice().reverse();
const memTxt = memOrdenada.map(m => `[${m.role}] ${m.content}`).join('\n') || '(sem historico)';

const temAudio = msgAtual.tem_audio === true && msgAtual.audio_base64;
const audioFalhou = msgAtual.tem_audio === true && msgAtual.audio_download_falhou;
const textoMostrado = temAudio
  ? '(o cliente enviou um audio. Voce recebe o audio inline na primeira parte do contents. Transcreva primeiro, depois decida acao.)'
  : (audioFalhou ? '(cliente enviou audio mas nao consegui baixar. Peca pra mandar em texto.)' : (msgAtual.texto || ''));

// ----- PROMPT DONO -----
const promptDono = `Voce e a Giulia Mascarenhas, secretaria pessoal do Thiago Nicezio.
Fala PT-BR direto, sem rodeio, sem hifens em listas, sem emojis a menos que ele use.

Voce recebe uma mensagem do Thiago (dono) e decide UMA acao.

ACOES (modo dono):
- salvar_ideia - guardar ideia/anotacao
- criar_lembrete - lembrar ele em data/hora
- agendar_mensagem - mandar mensagem pra OUTRA pessoa em data/hora futura
- enviar_agora - mandar mensagem pra OUTRA pessoa agora
- listar_ideias - mostrar ideias salvas (filtro opcional por tag)
- listar_lembretes - mostrar lembretes pendentes
- listar_leads - mostrar leads novos/em_atendimento
- listar_reunioes - mostrar reunioes pendentes/agendadas
- listar_notificacoes - mostrar notificacoes pendentes que voce gerou
- aprovar_reuniao - aprovar agendamento que cliente pediu (parametro: id_reuniao)
- apenas_responder - so conversar, sem acao

CONTATOS:
${contatosTxt}

HISTORICO:
${memTxt}

MENSAGEM ATUAL: "${textoMostrado}"
TIMESTAMP (Brasilia): ${msgAtual.timestamp_agora_brasilia}

Responda SOMENTE JSON valido sem markdown:
{
  "transcricao_audio": "se foi audio, escreva aqui o que o Thiago falou; senao deixe string vazia",
  "acao": "salvar_ideia|criar_lembrete|agendar_mensagem|enviar_agora|listar_ideias|listar_lembretes|listar_leads|listar_reunioes|listar_notificacoes|aprovar_reuniao|apenas_responder",
  "parametros": {
    "conteudo": "", "tags": [], "descricao": "",
    "disparar_em": "YYYY-MM-DD HH:MM:SS", "recorrencia": null,
    "destinatario_numero": "", "destinatario_nome": "",
    "texto": "", "filtro_tag": "", "id_reuniao": null
  },
  "resposta": "texto curto confirmando"
}

Regras: datas SEMPRE Brasilia; "daqui X min" calcula a partir do TIMESTAMP acima.`;

// ----- PROMPT RECEPCIONISTA -----
const leadTxt = lead
  ? `LEAD EXISTENTE: id=${lead.id} nome=${lead.nome||'(?)'} tipo=${lead.tipo_projeto||'(?)'}
  porte=${lead.porte||'(?)'} loc=${lead.localizacao||'(?)'} fase=${lead.fase||'(?)'} status=${lead.status}
  resumo=${lead.resumo||'(?)'}`
  : 'LEAD: cliente novo (nao cadastrado ainda)';

const promptRecepcionista = `Voce e a Giulia Mascarenhas, secretaria do Thiago Nicezio.

QUEM E O THIAGO NICEZIO
Empresario brasileiro, especialista em lagos ornamentais e Piscinas Praia.
Referencia nacional. Projetos no Brasil, Europa e Estados Unidos para grandes
empresas e empreendimentos de alto padrao.

ATUACAO
- ENG Solucoes (Socio) - sistemas de tratamento de agua com ozonio e UV para
  lagos ornamentais e Piscinas Praia, residencial a industrial.
- ABLP (Fundador e Presidente) - Associacao Brasileira de Lagos Ornamentais
  e Piscinas Naturais. Entidade que normatiza e profissionaliza o setor.
- Marca Pessoal Thiago Nicezio - projetos, consultoria tecnica, especificacao
  de sistemas de tratamento, renders 3D fotorrealistas, supervisao tecnica.

SERVICOS
Projeto de lago ornamental. Projeto de Piscina Praia. Consultoria tecnica.
Especificacao de sistemas de tratamento de agua. Renders e visualizacao 3D
fotorrealista. Supervisao tecnica de instalacao e start de sistemas.
O Thiago NAO executa obra civil - ele projeta, especifica e supervisiona.

DIFERENCIAIS (cite quando relevante)
Projetos no Brasil, Europa e EUA. Dominio tecnico em ozonio, UV e filtragem.
Fundador e Presidente da ABLP. Socio da ENG Solucoes.

REGRAS DE COMUNICACAO (CRITICAS)
- SEMPRE "Piscinas Praia". NUNCA "piscina natural" ou "piscina biologica".
- Em comunicacao formal, sempre "Thiago Nicezio".
- Reforcar projetos Brasil, Europa e EUA quando relevante.
- Citar a ABLP como pilar de autoridade quando agregar.
- Encerramento padrao em interacao formal completa: "Agua cristalina nao e promessa. E compromisso tecnico."
- NUNCA mencione anos de experiencia.
- NUNCA mencione execucao de obra civil.

TOM
Direto, tecnico, confiante. Sem hype. Profissional mas acessivel. Espelha o
cliente (formal->formal, casual->casual mas com profissionalismo). Frases curtas.
Sem emojis salvo se ele usar.

EQUIPE
- Eliana - contabilidade / financeiro / nota fiscal.
- ENG Solucoes - tecnico operacional de equipamento ozonio/UV ja entregue.
- CNPJ pra contratos: Sua Natureza Ecossistemas.

CONTATO PUBLICO
Site: thiagonicezio.com / Instagram: @thiagonicezio / E-mail: contato@filtrosuvc.com.br

POLITICA
1. So responde quando o cliente fala. Nao inicia.
2. Agendamento: voce coleta horario e marca pendente_aprovacao_thiago. Avisa
   ele e confirma com o cliente DEPOIS dele aprovar.
3. Gera notificacao pro Thiago em lead novo, agendamento, recado.
4. Se apresentar na primeira mensagem e seguir a conversa.

${leadTxt}

HISTORICO COM ESTE CONTATO:
${memTxt}

CONTATO: numero ${msgAtual.sender_numero}${msgAtual.sender_nome_push ? ', pushname: '+msgAtual.sender_nome_push : ''}
MENSAGEM ATUAL: "${textoMostrado}"
TIMESTAMP (Brasilia): ${msgAtual.timestamp_agora_brasilia}

ACOES (modo recepcionista):
- qualificar_lead - criar/atualizar dados do lead (nome, tipo_projeto, porte, localizacao, fase, resumo)
- agendar_reuniao - cliente quer falar com Thiago em data/hora. Cria pendente_aprovacao_thiago + notifica
- notificar_thiago - mandar recado pro Thiago
- encaminhar - direcionar pra Eliana (financeiro) ou ENG (tecnico)
- apenas_responder - conversa sem acao no banco

Responda SOMENTE JSON valido sem markdown:
{
  "transcricao_audio": "se foi audio escreva o que o cliente disse; senao string vazia",
  "acao": "qualificar_lead|agendar_reuniao|notificar_thiago|encaminhar|apenas_responder",
  "parametros": {
    "nome": "",
    "tipo_projeto": "lago_ornamental|piscina_praia|consultoria|render|supervisao|null",
    "porte": "residencial|comercial|industrial|alto_padrao|null",
    "localizacao": "",
    "fase": "ideia|em_andamento|pos_venda|imprensa|outro|null",
    "resumo": "",
    "agendado_para": "YYYY-MM-DD HH:MM:SS",
    "assunto_reuniao": "",
    "recado_thiago": "",
    "urgencia": "urgente|normal|info",
    "encaminhar_para": "eliana|eng_solucoes|null"
  },
  "resposta": "texto que voce manda pro cliente agora"
}`;

const systemPrompt = msgAtual.eh_thiago ? promptDono : promptRecepcionista;

// Montar parts do Gemini - audio inline se tiver
const parts = [];
if (temAudio) {
  parts.push({ inline_data: { mime_type: msgAtual.audio_mime || 'audio/ogg', data: msgAtual.audio_base64 } });
  parts.push({ text: 'Esta e a mensagem em audio do contato. Transcreva e decida a acao conforme o system prompt.' });
} else {
  parts.push({ text: msgAtual.texto || '(sem texto)' });
}

return [{
  json: {
    eh_thiago: msgAtual.eh_thiago,
    sender_numero: msgAtual.sender_numero,
    sender_nome_push: msgAtual.sender_nome_push,
    texto_original: msgAtual.texto || '',
    tem_audio: !!temAudio,
    timestamp_brasilia: msgAtual.timestamp_agora_brasilia,
    lead_id_atual: lead ? lead.id : null,
    gemini_body: {
      contents: [{ parts: parts }],
      systemInstruction: { parts: [{ text: systemPrompt }] },
      generationConfig: { temperature: 0.3, maxOutputTokens: 2000, responseMimeType: 'application/json' }
    }
  }
}];

// Parseia resposta Gemini e monta SQL/HTTP da acao escolhida
const prev = $('Montar Prompt').first().json;
const geminiResp = items[0].json;

let rawText = '';
try { rawText = geminiResp.candidates?.[0]?.content?.parts?.[0]?.text || ''; } catch(e) {}

function parseJson(s) {
  if (!s) return null;
  let t = String(s).trim().replace(/^```json\s*/i, '').replace(/```$/g, '').trim();
  const i = t.indexOf('{'); const j = t.lastIndexOf('}');
  if (i >= 0 && j > i) t = t.substring(i, j+1);
  try { return JSON.parse(t); } catch(e) { return null; }
}

const dec = parseJson(rawText) || { acao: 'apenas_responder', parametros: {}, resposta: 'Desculpa, tive um problema processando. Pode repetir?' };
const acao = dec.acao || 'apenas_responder';
const p = dec.parametros || {};
const esc = s => String(s == null ? '' : s).replace(/'/g, "''");
const escOrNull = s => (s == null || s === '') ? 'NULL' : `'${esc(s)}'`;

// Texto original: se foi audio usa transcricao, senao usa o texto que veio
const textoSalvarMemoria = prev.tem_audio
  ? (dec.transcricao_audio || '[audio sem transcricao]')
  : (prev.texto_original || '');

let acao_tipo = 'REPLY_ONLY';
let sql_query = '';
let send_to_number = '';
let send_text = '';

const senderNumero = prev.sender_numero;
const senderNomePush = prev.sender_nome_push || '';

if (prev.eh_thiago) {
  if (acao === 'salvar_ideia') {
    acao_tipo = 'DB_OP';
    const tagsArr = Array.isArray(p.tags) ? p.tags.filter(Boolean) : [];
    const tagsSql = tagsArr.length ? `ARRAY[${tagsArr.map(t=>`'${esc(t)}'`).join(',')}]::TEXT[]` : 'NULL';
    sql_query = `INSERT INTO giulia_ideias (conteudo, tags) VALUES ('${esc(p.conteudo)}', ${tagsSql}) RETURNING id, conteudo;`;
  } else if (acao === 'criar_lembrete') {
    acao_tipo = 'DB_OP';
    const rec = p.recorrencia ? `'${esc(p.recorrencia)}'` : 'NULL';
    sql_query = `INSERT INTO giulia_lembretes (descricao, disparar_em, recorrencia) VALUES ('${esc(p.descricao)}', '${esc(p.disparar_em)}'::TIMESTAMP, ${rec}) RETURNING id, descricao, disparar_em;`;
  } else if (acao === 'agendar_mensagem') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para) VALUES ('${esc(p.destinatario_numero)}', '${esc(p.destinatario_nome)}', '${esc(p.texto)}', '${esc(p.disparar_em || p.agendado_para)}'::TIMESTAMP) RETURNING id, destinatario_nome, agendado_para;`;
  } else if (acao === 'enviar_agora') {
    acao_tipo = 'SEND_NOW';
    send_to_number = String(p.destinatario_numero || '').replace(/[^0-9]/g,'');
    send_text = String(p.texto || '');
  } else if (acao === 'listar_ideias') {
    acao_tipo = 'DB_OP';
    const tag = p.filtro_tag ? esc(p.filtro_tag) : null;
    sql_query = tag
      ? `SELECT id, conteudo, tags, created_at FROM giulia_ideias WHERE '${tag}' = ANY(tags) ORDER BY created_at DESC LIMIT 20;`
      : `SELECT id, conteudo, tags, created_at FROM giulia_ideias ORDER BY created_at DESC LIMIT 20;`;
  } else if (acao === 'listar_lembretes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, descricao, disparar_em, recorrencia, status FROM giulia_lembretes WHERE status = 'pendente' ORDER BY disparar_em ASC LIMIT 20;`;
  } else if (acao === 'listar_leads') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, nome, numero, tipo_projeto, porte, localizacao, fase, resumo, status, criado_em FROM giulia_leads WHERE status IN ('novo','em_atendimento','agendado') ORDER BY criado_em DESC LIMIT 20;`;
  } else if (acao === 'listar_reunioes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, nome_cliente, numero_cliente, agendado_para, assunto, status FROM giulia_reunioes WHERE status IN ('pendente_aprovacao_thiago','agendada','confirmada') ORDER BY agendado_para ASC LIMIT 20;`;
  } else if (acao === 'listar_notificacoes') {
    acao_tipo = 'DB_OP';
    sql_query = `SELECT id, tipo, origem_nome, origem_numero, resumo, urgencia, criada_em FROM giulia_notificacoes_thiago WHERE status = 'pendente' ORDER BY criada_em DESC LIMIT 20;`;
  } else if (acao === 'aprovar_reuniao' && p.id_reuniao) {
    acao_tipo = 'DB_OP';
    sql_query = `UPDATE giulia_reunioes SET status = 'agendada', confirmada_em = NOW() WHERE id = ${parseInt(p.id_reuniao,10)} RETURNING id, nome_cliente, numero_cliente, agendado_para;`;
  }
} else {
  if (acao === 'qualificar_lead') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_leads (numero, nome, tipo_projeto, porte, localizacao, fase, resumo, status)
 VALUES ('${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, ${escOrNull(p.tipo_projeto)}, ${escOrNull(p.porte)}, ${escOrNull(p.localizacao)}, ${escOrNull(p.fase)}, ${escOrNull(p.resumo)}, 'em_atendimento')
 ON CONFLICT (numero) DO UPDATE SET
   nome = COALESCE(EXCLUDED.nome, giulia_leads.nome),
   tipo_projeto = COALESCE(EXCLUDED.tipo_projeto, giulia_leads.tipo_projeto),
   porte = COALESCE(EXCLUDED.porte, giulia_leads.porte),
   localizacao = COALESCE(EXCLUDED.localizacao, giulia_leads.localizacao),
   fase = COALESCE(EXCLUDED.fase, giulia_leads.fase),
   resumo = COALESCE(EXCLUDED.resumo, giulia_leads.resumo),
   status = CASE WHEN giulia_leads.status = 'novo' THEN 'em_atendimento' ELSE giulia_leads.status END,
   atualizado_em = NOW()
 RETURNING id, nome, tipo_projeto;
 INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia)
 SELECT 'lead_novo', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Lead qualificado: ' || COALESCE(${escOrNull(p.tipo_projeto)}, '?') || ' / ' || COALESCE(${escOrNull(p.porte)}, '?') || ' / ' || COALESCE(${escOrNull(p.localizacao)}, '?') || E'\n' || COALESCE(${escOrNull(p.resumo)}, ''), 'normal'
 WHERE NOT EXISTS (SELECT 1 FROM giulia_notificacoes_thiago WHERE origem_numero = '${esc(senderNumero)}' AND tipo = 'lead_novo' AND status = 'pendente');`;
  } else if (acao === 'agendar_reuniao') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_leads (numero, nome, status) VALUES ('${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'agendado') ON CONFLICT (numero) DO UPDATE SET status = 'agendado', atualizado_em = NOW();
 INSERT INTO giulia_reunioes (lead_id, numero_cliente, nome_cliente, agendado_para, assunto, status)
 VALUES ((SELECT id FROM giulia_leads WHERE numero = '${esc(senderNumero)}'), '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, '${esc(p.agendado_para)}'::TIMESTAMP, ${escOrNull(p.assunto_reuniao)}, 'pendente_aprovacao_thiago') RETURNING id, agendado_para;
 INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia)
 VALUES ('agendamento_pendente', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Cliente pediu reuniao em ${esc(p.agendado_para)}. Assunto: ' || COALESCE(${escOrNull(p.assunto_reuniao)}, '(?)') || E'\nPra aprovar, manda: aprovar reuniao <id>', ${escOrNull(p.urgencia || 'normal')});`;
  } else if (acao === 'notificar_thiago') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia) VALUES ('recado', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, '${esc(p.recado_thiago || dec.resposta || '')}', ${escOrNull(p.urgencia || 'normal')}) RETURNING id, resumo;`;
  } else if (acao === 'encaminhar') {
    acao_tipo = 'DB_OP';
    sql_query = `INSERT INTO giulia_notificacoes_thiago (tipo, origem_numero, origem_nome, resumo, urgencia) VALUES ('encaminhamento', '${esc(senderNumero)}', ${escOrNull(p.nome || senderNomePush)}, 'Encaminhei para ' || COALESCE(${escOrNull(p.encaminhar_para)}, '?') || ': ' || ${escOrNull(p.resumo || dec.resposta || '')}, 'info') RETURNING id;`;
  }
}

return [{
  json: {
    eh_thiago: prev.eh_thiago,
    sender_numero: senderNumero,
    sender_nome_push: senderNomePush,
    texto_original: textoSalvarMemoria,
    transcricao_audio: dec.transcricao_audio || '',
    tem_audio: prev.tem_audio,
    acao,
    acao_tipo,
    sql_query,
    send_to_number,
    send_text,
    resposta: dec.resposta || 'Ok.',
    gemini_raw: rawText.substring(0, 500)
  }
}];

const dec = $('Decidir Acao').first().json;
const acao = dec.acao;
let textoResposta = dec.resposta || 'Ok.';

function fmtDt(d){
  if (!d) return '';
  const dt = new Date(d);
  return dt.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', dateStyle: 'short', timeStyle: 'short' });
}

if (acao === 'listar_ideias') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.conteudo);
  if (!rows.length) textoResposta = 'Nenhuma ideia salva ainda.';
  else textoResposta = 'Tuas ideias salvas:\n' + rows.map((r,i)=>{
    const tags = Array.isArray(r.tags)&&r.tags.length ? ` [${r.tags.join(', ')}]` : '';
    return `${i+1}. ${r.conteudo}${tags}`;
  }).join('\n');
}
if (acao === 'listar_lembretes') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.descricao);
  if (!rows.length) textoResposta = 'Nenhum lembrete pendente.';
  else textoResposta = 'Lembretes pendentes:\n' + rows.map((r,i)=>{
    const rec = r.recorrencia ? ` (${r.recorrencia})` : '';
    return `${i+1}. ${fmtDt(r.disparar_em)} - ${r.descricao}${rec}`;
  }).join('\n');
}
if (acao === 'listar_leads') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.numero);
  if (!rows.length) textoResposta = 'Nenhum lead em atendimento.';
  else textoResposta = 'Leads:\n' + rows.map((r,i)=>{
    return `${i+1}. ${r.nome || '(sem nome)'} - ${r.numero} - ${r.tipo_projeto||'?'}/${r.porte||'?'} - ${r.localizacao||'?'} - status:${r.status}`;
  }).join('\n');
}
if (acao === 'listar_reunioes') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.nome_cliente !== undefined);
  if (!rows.length) textoResposta = 'Nenhuma reuniao pendente.';
  else textoResposta = 'Reunioes:\n' + rows.map((r,i)=>{
    return `${i+1}. id=${r.id} ${fmtDt(r.agendado_para)} - ${r.nome_cliente||'(?)'} (${r.numero_cliente}) - ${r.assunto||'sem assunto'} - ${r.status}`;
  }).join('\n');
}
if (acao === 'listar_notificacoes') {
  const rows = $input.all().map(i => i.json).filter(r => r && r.resumo);
  if (!rows.length) textoResposta = 'Sem notificacoes pendentes.';
  else textoResposta = 'Notificacoes:\n' + rows.map((r,i)=>{
    return `${i+1}. [${r.urgencia||'normal'}] ${r.tipo} - ${r.origem_nome||r.origem_numero}: ${r.resumo}`;
  }).join('\n');
}
if (acao === 'enviar_agora') {
  const status = $input.first()?.json?.status || $input.first()?.json?.statusCode;
  if (status && String(status).match(/^[45]/)) textoResposta = `Tive problema ao mandar: ${status}.`;
}

return [{
  json: {
    sender_numero: dec.sender_numero,
    texto_original: dec.texto_original,
    resposta_final: textoResposta
  }
}];

